 "content": "def transform(grid):
    """Rebuild a self-similar N-by-N tile mask hidden by a solid 3 band."""
    h, w = len(grid), len(grid[0])
    n = next(k for k in range(1, 31) if k * k + k - 1 == h and k * k + k - 1 == w)
    stride = n + 1

    # Recover the N-by-N motif from any unoccluded tile. Tiles contain only
    # 0/2; solid 3 bands can hide a complete motif row or column.
    motif = None
    for tr in range(n):
        for tc in range(n):
            r0, c0 = tr * stride, tc * stride
            tile = [grid[r0 + r][c0:c0 + n] for r in range(n)]
            if all(v in (0, 2) for row in tile for v in row) and any(2 in row for row in tile):
                motif = [[1 if v == 2 else 0 for v in row] for row in tile]
                break
        if motif is not None:
            break
    if motif is None:
        raise ValueError('no unoccluded motif tile found')

    out = [[0] * w for _ in range(h)]
    for tr in range(n):
        for tc in range(n):
            if motif[tr][tc]:
                r0, c0 = tr * stride, tc * stride
                for r in range(n):
                    for c in range(n):
                        if motif[r][c]:
                            out[r0 + r][c0 + c] = 2
                out[r0 + tr][c0 + tc] = 8
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.loads(sys.stdin.read()))))
